51: // NewScanner creates a new Scanner, and can take options to apply to the scanner.
52: func NewScanner(options ...Option) (*Scanner, error) {
53: 	scanner := Scanner{
54: 		interactive: isatty.IsTerminal(os.Stdin.Fd()),
55: 	}
56: 
57: 	for _, option := range options {
